CREATE TABLE "user_role_assignments" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"user_id" TEXT NOT NULL,"role_id" TEXT NOT NULL,"environment_id" TEXT,"source" TEXT NOT NULL DEFAULT 'manual',PRIMARY KEY ("id"),FOREIGN KEY (environment_id) REFERENCES environments(id) ON DELETE CASCADE,FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE "user_sessions" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"user_id" TEXT NOT NULL,"refresh_token_hash" TEXT NOT NULL,"user_agent" TEXT,"ip_address" TEXT,"source" TEXT,"last_used_at" datetime NOT NULL,"expires_at" datetime NOT NULL,"revoked_at" datetime,PRIMARY KEY ("id"),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE (refresh_token_hash));
CREATE TABLE "users" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"username" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"display_name" TEXT,"email" TEXT,"last_login" datetime,"locale" TEXT,"time_format" TEXT NOT NULL DEFAULT 'auto',"font_size" INTEGER,"preferences" TEXT,"requires_password_change" numeric NOT NULL DEFAULT false,"has_avatar" numeric NOT NULL DEFAULT false,"disabled_at" datetime,"ui_preferences" TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(ui_preferences)),PRIMARY KEY ("id"),CHECK ((time_format IN ('auto', '12h', '24h'))),UNIQUE (username),CHECK ("preferences" IS NULL OR json_valid("preferences")));
CREATE TABLE "volume_backup_policies" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"volume_name" TEXT NOT NULL,"enabled" numeric NOT NULL DEFAULT false,"schedule" TEXT NOT NULL,"retention_count" INTEGER NOT NULL DEFAULT 7,"stop_containers" numeric NOT NULL DEFAULT false,"local_enabled" numeric NOT NULL DEFAULT true,"target_id" TEXT NOT NULL DEFAULT 'local',PRIMARY KEY ("id"));
CREATE TABLE "volume_backups" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"volume_name" TEXT NOT NULL,"size" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'succeeded',"trigger" TEXT NOT NULL DEFAULT 'manual',"destination" TEXT NOT NULL DEFAULT 'local',"format" TEXT NOT NULL DEFAULT 'archive',"snapshot_unavailable_at" datetime,"local_snapshot_id" TEXT,"policy_id" TEXT,"error" TEXT,"stop_containers" numeric NOT NULL DEFAULT false,"stopped_containers" TEXT,"error_code" TEXT,"activity_id" TEXT,PRIMARY KEY ("id"),CHECK (stopped_containers IS NULL OR json_valid(stopped_containers)));
CREATE TABLE "volume_restore_runs" ("id" TEXT NOT NULL,"volume_name" TEXT NOT NULL,"kind" TEXT NOT NULL,"backup_id" TEXT,"safety_backup_id" TEXT,"input_path" TEXT,"input_sha256" TEXT,"phase" TEXT NOT NULL,"status" TEXT NOT NULL,"pending_restart" numeric NOT NULL DEFAULT false,"stopped_containers" TEXT,"error_code" TEXT,"error_reason" TEXT,"activity_id" TEXT,"started_at" datetime NOT NULL,"finished_at" datetime,"mode" TEXT NOT NULL DEFAULT 'replace',"new_volume_name" TEXT,"created_volume" numeric NOT NULL DEFAULT false,"cleanup_pending" numeric NOT NULL DEFAULT false,PRIMARY KEY ("id"),CHECK (kind IN ('full','files','upload')),CHECK (phase IN ('preparing','writing','done')),CHECK (status IN ('running','succeeded','failed','partial')),CHECK (stopped_containers IS NULL OR json_valid(stopped_containers)),CHECK (mode IN ('replace','new')));
CREATE TABLE "vulnerability_ignores" ("id" TEXT NOT NULL,"environment_id" TEXT NOT NULL,"image_id" TEXT NOT NULL,"vulnerability_id" TEXT NOT NULL,"pkg_name" TEXT NOT NULL,"installed_version" TEXT NOT NULL,"reason" TEXT,"created_by" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),PRIMARY KEY ("id"));
CREATE TABLE "vulnerability_reports" ("image_id" TEXT NOT NULL,"data" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,PRIMARY KEY ("image_id"),CHECK (data IS NULL OR json_valid(data)));
CREATE TABLE "vulnerability_risk_snapshots" ("snapshot_date" TEXT NOT NULL,"scoring_version" INTEGER NOT NULL DEFAULT 1,"risk_score" INTEGER NOT NULL DEFAULT 0,"risk_band" TEXT NOT NULL DEFAULT 'none',"critical_count" INTEGER NOT NULL DEFAULT 0,"high_count" INTEGER NOT NULL DEFAULT 0,"medium_count" INTEGER NOT NULL DEFAULT 0,"low_count" INTEGER NOT NULL DEFAULT 0,"unknown_count" INTEGER NOT NULL DEFAULT 0,"findings_count" INTEGER NOT NULL DEFAULT 0,"known_exploited_count" INTEGER NOT NULL DEFAULT 0,"overdue_known_exploited_count" INTEGER NOT NULL DEFAULT 0,"high_epss_count" INTEGER NOT NULL DEFAULT 0,"exposed_critical_high_count" INTEGER NOT NULL DEFAULT 0,"fixable_count" INTEGER NOT NULL DEFAULT 0,"images_scanned" INTEGER NOT NULL DEFAULT 0,"images_total" INTEGER NOT NULL DEFAULT 0,"scored_images" INTEGER NOT NULL DEFAULT 0,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,PRIMARY KEY ("snapshot_date"));
CREATE TABLE "vulnerability_scan_items" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,"image_id" TEXT NOT NULL,"vulnerability_id" TEXT NOT NULL,"pkg_name" TEXT NOT NULL,"installed_version" TEXT NOT NULL DEFAULT '',"fixed_version" TEXT NOT NULL DEFAULT '',"severity" TEXT NOT NULL,"severity_rank" INTEGER NOT NULL DEFAULT 0,"pkg_class" TEXT NOT NULL DEFAULT '',"pkg_type" TEXT NOT NULL DEFAULT '',"title" TEXT NOT NULL DEFAULT '',"cvss_score" REAL,"details" TEXT,FOREIGN KEY (image_id) REFERENCES vulnerability_scans(id) ON DELETE CASCADE,CHECK (details IS NULL OR json_valid(details)));
CREATE TABLE "vulnerability_scan_notifications" ("registration_id" TEXT NOT NULL,"activity_id" TEXT NOT NULL,"created_at" datetime NOT NULL,"status" TEXT NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"lease_until" datetime,PRIMARY KEY ("registration_id","activity_id"),CHECK (status IN ('pending','sending','sent','failed','expired','unconfigured')),CHECK (attempts >= 0),CHECK ((status = 'sending') = (lease_until IS NOT NULL)));
CREATE TABLE "vulnerability_scan_runs" ("activity_id" TEXT NOT NULL,"environment_id" TEXT NOT NULL,"origin" TEXT NOT NULL,"scope" TEXT NOT NULL,"status" TEXT NOT NULL,"error_code" TEXT NOT NULL DEFAULT '',"started_at" datetime NOT NULL,"finished_at" datetime,"targets" INTEGER NOT NULL DEFAULT 0,"scanned" INTEGER NOT NULL DEFAULT 0,"failed" INTEGER NOT NULL DEFAULT 0,"skipped" INTEGER NOT NULL DEFAULT 0,"critical" INTEGER NOT NULL DEFAULT 0,"high" INTEGER NOT NULL DEFAULT 0,"medium" INTEGER NOT NULL DEFAULT 0,"low" INTEGER NOT NULL DEFAULT 0,"unknown" INTEGER NOT NULL DEFAULT 0,"new_critical" INTEGER NOT NULL DEFAULT 0,"new_high" INTEGER NOT NULL DEFAULT 0,"new_findings" TEXT NOT NULL DEFAULT '[]',PRIMARY KEY ("activity_id"),CHECK (origin IN ('manual','scheduled')),CHECK (scope IN ('in-use','all')),CHECK (status IN ('running','completed','partial','cancelled','failed','interrupted')),CHECK (targets>=0),CHECK (scanned>=0),CHECK (failed>=0),CHECK (skipped>=0),CHECK (critical>=0),CHECK (high>=0),CHECK (medium>=0),CHECK (low>=0),CHECK (unknown>=0),CHECK (new_critical>=0),CHECK (new_high>=0),CHECK ("new_findings" IS NULL OR json_valid("new_findings")));
CREATE TABLE "vulnerability_scans" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"image_name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"scan_time" datetime NOT NULL,"duration" INTEGER NOT NULL DEFAULT 0,"critical_count" INTEGER NOT NULL DEFAULT 0,"high_count" INTEGER NOT NULL DEFAULT 0,"medium_count" INTEGER NOT NULL DEFAULT 0,"low_count" INTEGER NOT NULL DEFAULT 0,"unknown_count" INTEGER NOT NULL DEFAULT 0,"total_count" INTEGER NOT NULL DEFAULT 0,"vulnerabilities" TEXT,"error" TEXT,"scanner_version" TEXT,"fixable_count" INTEGER,"scan_policy" TEXT NOT NULL DEFAULT '',"attempt_id" TEXT,"platform" TEXT,"error_code" TEXT,"started_at" datetime,"completed_at" datetime,"completed_attempt_id" TEXT,"completed_platform" TEXT,PRIMARY KEY ("id"),CHECK ("vulnerabilities" IS NULL OR json_valid("vulnerabilities")));
CREATE TABLE "vulnerability_threat_intel" ("cve_id" TEXT NOT NULL,"known_exploited" numeric NOT NULL DEFAULT false,"kev_date_added" TEXT NOT NULL DEFAULT '',"kev_due_date" TEXT NOT NULL DEFAULT '',"kev_ransomware" numeric NOT NULL DEFAULT false,"epss_score" REAL,"epss_percentile" REAL,"epss_checked_at" datetime,"updated_at" datetime,PRIMARY KEY ("cve_id"));
